def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = []
    op = []
    for h in history:
        me.append(h[0])
        op.append(h[1])

    opp_c = 0
    me_d = 0
    for i in range(n):
        if op[i] == 'C':
            opp_c += 1
        if me[i] == 'D':
            me_d += 1
    opp_d = n - opp_c

    w = n if n < 12 else 12
    rec_opp_d = 0
    rec_opp_c = 0
    rec_me_d = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1
        if me[i] == 'D':
            rec_me_d += 1

    opp_d_run = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        opp_d_run += 1
        i -= 1

    me_d_run = 0
    i = n - 1
    while i >= 0 and me[i] == 'D':
        me_d_run += 1
        i -= 1

    dd_run = 0
    i = n - 1
    while i >= 0 and me[i] == 'D' and op[i] == 'D':
        dd_run += 1
        i -= 1

    tol = 0
    pun = 0
    st = 1
    if n > 30:
        st = n - 30
    for i in range(st, n):
        if me[i - 1] == 'D':
            if op[i] == 'C':
                tol += 1
            else:
                pun += 1

    last_cc = -1
    for i in range(n - 1, -1, -1):
        if me[i] == 'C' and op[i] == 'C':
            last_cc = i
            break

    we_started = False
    opp_started = False
    opp_punished = False

    if last_cc + 1 < n:
        a = me[last_cc + 1]
        b = op[last_cc + 1]
        if a == 'D' and b == 'C':
            we_started = True
        elif a == 'C' and b == 'D':
            opp_started = True
        else:
            if rec_me_d >= rec_opp_d:
                we_started = True
            else:
                opp_started = True

    if opp_started:
        check_start = last_cc + 2
        if check_start < 0:
            check_start = 1
        for j in range(check_start, n):
            if me[j] == 'D':
                opp_punished = True
                break

    last_me = me[-1]
    last_opp = op[-1]

    if last_opp == 'D':
        if opp_d == n:
            return 'D'
        if opp_d_run >= 5 or rec_opp_d >= 10:
            return 'D'
        if n >= 20 and opp_d > opp_c + 15 and rec_opp_d >= 6:
            return 'D'

    if rec_opp_d >= 10 and opp_d > opp_c + 3:
        return 'D'

    if last_opp == 'D':
        if opp_started:
            if opp_d_run >= 3 or rec_opp_d >= 6 or opp_d > opp_c + 5:
                return 'D'
            if opp_punished and n >= 10 and opp_c >= n - 6 and opp_d_run <= 1:
                return 'C'
            return 'D'

        if we_started:
            if opp_d_run >= 4 or rec_opp_d >= 8:
                return 'D'
            if n >= 20 and opp_d > opp_c + 10 and rec_opp_d >= 5:
                return 'D'
            return 'C'

        if opp_d_run >= 3 or rec_opp_d >= 7:
            return 'D'
        if last_me == 'C':
            return 'D'
        return 'D'

    if opp_d == 0:
        if n == 85 and me_d == 0:
            return 'D'
        if me_d > 0 and n >= 87:
            return 'D'

    if tol >= 1 and pun == 0 and rec_opp_c >= 10 and opp_d <= 5 and n >= 86:
        return 'D'

    if n >= 96 and opp_d == 0 and me_d > 0:
        return 'D'

    return 'C'
